function ema(arr, alpha){ if(alpha<=0||alpha>1) return []; var out=[], prev=null; for(var i=0;i<arr.length;i++){ prev = prev===null?arr[i]:alpha*arr[i]+(1-alpha)*prev; out.push(prev); } return out; }
var EXPORTS={sma:sma, ema:ema};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
